units.explanation:
图上的 DFS（深度优先搜索）是图论最基础的遍历算法。

基本思路：从起点出发，沿一条路走到底，走不通就回退换路。

与树上的 DFS 不同，图可能有环，所以必须用 visited 数组标记已访问节点，防止死循环。

DFS 标准模板：
void dfs(int u) {
    visited[u] = true;
    for (int v : adj[u])
        if (!visited[v])
            dfs(v);
}

时间复杂度：O(V + E)，每个节点和每条边最多访问一次。
空间复杂度：O(V)，visited 数组 + 递归栈深度。

常见应用：
- 连通性判断
- 环检测（有向图/无向图）
- 求连通分量个数
- 拓扑排序
- 二分图判定

units.exampleCode:
#include <iostream>
#include <vector>
using namespace std;

int n, m;
vector<int> adj[10005];
bool visited[10005];

void dfs(int u) {
    visited[u] = true;
    cout << u << " ";
    for (int v : adj[u]) {
        if (!visited[v]) {
            dfs(v);
        }
    }
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    dfs(1);
    return 0;
}

units.explanation:
图上的 BFS（广度优先搜索）从起点出发，逐层向外扩展。

BFS 用队列实现：
1. 起点入队，标记 visited
2. 循环：取出队首，将未访问邻居入队
3. 队列为空时结束

BFS 标准模板：
queue<int> q;
q.push(start);
visited[start] = true;
while (!q.empty()) {
    int u = q.front(); q.pop();
    for (int v : adj[u])
        if (!visited[v]) {
            visited[v] = true;
            q.push(v);
        }
}

时间复杂度：O(V + E)
空间复杂度：O(V)

BFS 的核心优势：在无权图中，BFS 第一次到达某节点时的距离就是最短距离。因此 BFS 天然适合求无权图最短路径。

BFS vs DFS：
- BFS：逐层扩展，空间 O(V)，适合求最短路
- DFS：深入到底再回溯，空间 O(深度)，适合连通性/回溯

units.exampleCode:
#include <iostream>
#include <vector>
#include <queue>
using namespace std;

int n, m;
vector<int> adj[10005];
bool visited[10005];
int dist[10005];

void bfs(int start) {
    queue<int> q;
    q.push(start);
    visited[start] = true;
    dist[start] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    bfs(1);
    for (int i = 1; i <= n; i++)
        cout << "dist[" << i << "]=" << dist[i] << endl;
    return 0;
}

