#include <iostream>
#include <vector>
#include <queue>
using namespace std;

int n, m;
vector<int> adj[10005];
int color[10005]; // -1=未染色, 0/1=颜色

bool isBipartite() {
    for (int i = 1; i <= n; i++) color[i] = -1;
    for (int s = 1; s <= n; s++) {
        if (color[s] != -1) continue;
        color[s] = 0;
        queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : adj[u]) {
                if (color[v] == -1) {
                    color[v] = 1 - color[u];
                    q.push(v);
                } else if (color[v] == color[u]) {
                    return false;
                }
            }
        }
    }
    return true;
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    cout << (isBipartite() ? "Yes" : "No") << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
using namespace std;

int n, m;
vector<int> adj[10005];
int indeg[10005];

int main() {
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
    }
    for (int u = 1; u <= n; u++)
        for (int v : adj[u])
            indeg[v]++;
    queue<int> q;
    for (int i = 1; i <= n; i++)
        if (indeg[i] == 0) q.push(i);
    vector<int> topo;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        topo.push_back(u);
        for (int v : adj[u]) {
            indeg[v]--;
            if (indeg[v] == 0) q.push(v);
        }
    }
    if (topo.size() == n) {
        for (int x : topo) cout << x << " ";
    } else {
        cout << "图中有环！" << endl;
    }
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int n, m;
vector<int> adj[10005];
int state[10005]; // 0=未访问, 1=访问中, 2=已完成
bool hasCycle = false;

void dfs(int u) {
    state[u] = 1;
    for (int v : adj[u]) {
        if (state[v] == 0) {
            dfs(v);
        } else if (state[v] == 1) {
            hasCycle = true;
        }
    }
    state[u] = 2;
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
    }
    for (int i = 1; i <= n; i++)
        if (state[i] == 0)
            dfs(i);
    cout << (hasCycle ? "不是 DAG" : "是 DAG") << endl;
    return 0;
}
